class R{String s(boolean p,String[]I){long x=0,y=0,a=0,e=0;for(var L:I){var w=L.split(" ");String A=w[0],B=w[1],C=w[2];int d,n;if(p){d="RDLU".indexOf(A);n=new Integer(B);}else{d=C.charAt(7)-48;n=Integer.parseInt(C.substring(2,7),16);}long X=x+(d%2<1?1-d:0L)*n,Y=y+(d%2>0?2-d:0L)*n;a+=x*Y-X*y;e+=n;x=X;y=Y;}return""+(Math.abs(a)/2+e/2+1);}}
